// Questionários objetivos por livro (80% para aprovar). Verificam se o estudante entendeu o que o autor
// defende, não se concorda com ele. Cada explicação termina indicando o que revisar em caso de erro.
// Referências por livro, capítulo ou trecho conhecido; nenhuma página citada.
// Formato igual ao das aulas: { tipo: 'mc', enunciado, opcoes, correta (índice), explicacao }.

// A posição da resposta certa é girada por um hash do enunciado: estável entre visitas, mas sem padrão a adivinhar.
const hash = (s) => [...s].reduce((h, c) => (h * 31 + c.charCodeAt(0)) >>> 0, 7);
function Q(enunciado, opcoes, correta, explicacao, revisar) {
  const n = opcoes.length, k = hash(enunciado) % n;
  return { tipo: 'mc', enunciado, opcoes: [...opcoes.slice(k), ...opcoes.slice(0, k)], correta: (correta - k + n) % n, explicacao: `${explicacao} Revise: ${revisar}.` };
}

